"""
Assemble the shifted-resonance joint generator series.

The measured transition includes the static lattice relaxation shift, while the reduced dynamics retains its compensating interaction counterterm.

Returns
-------
result : np.ndarray     Complex shape (K+1,D*D,D*D), ordinary coefficients of the complete     column-vectorized Liouvillian L(lambda). Include coherent dynamics,     the supplied phonon series, independent radiative losses, and the     interaction counterterm compensating the static polaron shift.     A population-decay rate k multiplies c rho c^dagger-{c^dagger c,rho}/2.     Coefficient j has units ps**(j-1).
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def total_liouvillian(operators: "np.ndarray", phonon_series: "np.ndarray", gamma: float, widths: "np.ndarray", alpha: float, cutoff: float) -> "np.ndarray":
    """Assemble the joint Liouvillian Taylor series in the shifted convention.

    Parameters
    ----------
    operators : np.ndarray
        Complex shape (N+4,D,D), the joint_operators stack H0,V,A,lowering
        operators, with the stated polaron-shifted dot detuning.
    phonon_series : np.ndarray
        Complex shape (K+1,D*D,D*D), 0<=K<=6, from phonon_superoperator
        for this Hamiltonian family and its complete complex bath response.
    gamma : float
        Positive dot population-decay rate in ps^-1.
    widths : np.ndarray
        Positive shape (N,), probe population-decay rates in ps^-1.
    alpha : float
        Nonnegative strength of the same acoustic bath, in ps^2.
    cutoff : float
        Cutoff of the same bath in ps^-1, 0.8<=cutoff<=3.

    Returns
    -------
    result : np.ndarray
        Complex shape (K+1,D*D,D*D), ordinary coefficients of the complete
        column-vectorized Liouvillian L(lambda). Include coherent dynamics,
        the supplied phonon series, independent radiative losses, and the
        interaction counterterm compensating the static polaron shift.
        A population-decay rate k multiplies c rho c^dagger-{c^dagger c,rho}/2.
        Coefficient j has units ps**(j-1).
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np

def _oracle_total_liouvillian(operators: "np.ndarray", phonon_series: "np.ndarray", gamma: float, widths: "np.ndarray", alpha: float, cutoff: float) -> "np.ndarray":
    h0,v,a=operators[:3];lowering=operators[3:];eye=np.eye(len(h0))
    delta_p=-alpha*np.sqrt(np.pi)*cutoff**3/4
    h=h0-delta_p*a
    result=phonon_series.copy()
    result[0]+=-1j*(np.kron(eye,h)-np.kron(h.T,eye))
    if len(result)>1:
        result[1]+=-1j*(np.kron(eye,v)-np.kron(v.T,eye))
    for decay,op in zip([gamma,*widths],lowering):
        population=op.conj().T@op
        result[0]+=decay*(np.kron(op.conj(),op)-.5*np.kron(eye,population)-.5*np.kron(population.T,eye))
    return result

